            *p++ = hex_chars[s[i] >> 4];
            *p++ = hex_chars[s[i] & 0xF];
        } else {
            *p++ = ' ';
            *p++ = ' ';
        }
        *p++ = (i == 7) ? ' ' : ' ';
    }
    p[-1] = ' ';

    *p++ = ' ';
    *p++ = ' ';

    for (i = 0; i < 16; ++i) {
        if (i < len) {
            unsigned char c = s[i];
            *p++ = (c >= 0x20 && c <= 0x7E) ? c : '.';
        } else {
            *p++ = ' ';
        }
    }

    *p = '\0';

